insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0401$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Enthalpy of Formation and Hess's Law$q$, $q$Answer a real JAMB 2003 question on Enthalpy of Formation and Hess's Law.$q$, $q$[{"conceptId": "ji3evn", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "-262 kJ/mol suggests one of the reactant or product values wasn't included correctly in the sum \u2014 a partial rather than complete application of Hess's law across all three given values.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "+42 kJ/mol has the correct magnitude but the wrong sign \u2014 likely from reversing the products-minus-reactants order in the Hess's law formula.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "+262 kJ/mol carries over the same magnitude error as option A while also flipping the sign \u2014 compounding both an incomplete sum and a sign reversal.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$CO(g) + H2O(g) ⇌ CO2(g) + H2(g). Calculate the standard heat change if the standard enthalpies of formation of CO2(g), H2O(g) and CO(g) in kJ mol-1 are −394, −242 and −110 respectively.$q$, $q$[{"label": "A", "text": "-262kJmol-1", "isCorrect": false}, {"label": "B", "text": "-42 kJmol-1", "isCorrect": true}, {"label": "C", "text": "+42 kJmol-1", "isCorrect": false}, {"label": "D", "text": "+262 kJmol-1", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$ΔH°rxn = ΣΔHf(products) − ΣΔHf(reactants) = [(-394) + 0] − [(-110) + (-242)] = -394 − (-352) = -394 + 352 = -42 kJ/mol. (H2(g), being an element in its standard state, has ΔHf = 0.)$q$, $q$live$q$, $q$A: -262 kJ/mol suggests one of the reactant or product values wasn't included correctly in the sum — a partial rather than complete application of Hess's law across all three given values. C: +42 kJ/mol has the correct magnitude but the wrong sign — likely from reversing the products-minus-reactants order in the Hess's law formula. D: +262 kJ/mol carries over the same magnitude error as option A while also flipping the sign — compounding both an incomplete sum and a sign reversal.$q$),
($q$chemistry_0402$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Entropy and Disorder$q$, $q$Answer a real JAMB 2003 question on Entropy and Disorder.$q$, $q$[{"conceptId": "s55vck", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Dissolving increases disorder as the ordered crystal breaks apart and disperses \u2014 this is a positive, not negative, change; negative entropy would mean the system became MORE ordered, the opposite of what happens.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "Dissolution is a clear physical process that changes the arrangement of particles from ordered (solid) to disordered (dispersed in solution) \u2014 there is a real, non-zero entropy change involved.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "'A minimum entropy change' doesn't correctly describe what happens \u2014 dissolving a solid into a liquid produces a substantial, not minimal, increase in disorder/entropy.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$When sugar is dissolved in tea, the reaction is always accompanied by$q$, $q$[{"label": "A", "text": "positive entropy change", "isCorrect": true}, {"label": "B", "text": "negative entropy change", "isCorrect": false}, {"label": "C", "text": "no entropy change", "isCorrect": false}, {"label": "D", "text": "a minimum entropy change", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Dissolving a solid (sugar, an ordered crystal lattice) into a liquid disperses its particles randomly throughout the solution, increasing the overall disorder of the system — this increase in disorder is a positive entropy change.$q$, $q$live$q$, $q$B: Dissolving increases disorder as the ordered crystal breaks apart and disperses — this is a positive, not negative, change; negative entropy would mean the system became MORE ordered, the opposite of what happens. C: Dissolution is a clear physical process that changes the arrangement of particles from ordered (solid) to disordered (dispersed in solution) — there is a real, non-zero entropy change involved. D: 'A minimum entropy change' doesn't correctly describe what happens — dissolving a solid into a liquid produces a substantial, not minimal, increase in disorder/entropy.$q$),
($q$chemistry_0403$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Electrolytes vs Non-Electrolytes$q$, $q$Answer a real JAMB 2003 question on Electrolytes vs Non-Electrolytes.$q$, $q$[{"conceptId": "yckr2s", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Alcohol is a covalent molecular substance that doesn't dissociate into ions in solution \u2014 without mobile ions, it can't conduct electricity and isn't an electrolyte.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Solid KOH does contain ions, but they're fixed in a rigid crystal lattice and can't move to carry current \u2014 it only becomes a conducting electrolyte once dissolved in water or melted.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "Mercury conducts electricity, but through the free movement of electrons (like all metals), not through ions \u2014 this is metallic conduction, a fundamentally different mechanism from electrolytic (ionic) conduction.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Which of the following is an electrolyte?$q$, $q$[{"label": "A", "text": "Alcohol", "isCorrect": false}, {"label": "B", "text": "Sodium acetate solution", "isCorrect": true}, {"label": "C", "text": "Solid potassium hydroxide", "isCorrect": false}, {"label": "D", "text": "Mercury", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$An electrolyte is a substance that conducts electricity via ion movement when dissolved or molten. Sodium acetate SOLUTION has mobile dissociated ions and conducts electricity — a true electrolyte. Alcohol is molecular and doesn't ionise. Solid KOH has ions locked in a rigid lattice (not mobile) so it doesn't conduct until dissolved or molten. Mercury conducts via free electrons (metallic conduction), not via ions, so it isn't classified as an electrolyte.$q$, $q$live$q$, $q$A: Alcohol is a covalent molecular substance that doesn't dissociate into ions in solution — without mobile ions, it can't conduct electricity and isn't an electrolyte. C: Solid KOH does contain ions, but they're fixed in a rigid crystal lattice and can't move to carry current — it only becomes a conducting electrolyte once dissolved in water or melted. D: Mercury conducts electricity, but through the free movement of electrons (like all metals), not through ions — this is metallic conduction, a fundamentally different mechanism from electrolytic (ionic) conduction.$q$),
($q$chemistry_0404$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Laboratory Preparation of Chlorine$q$, $q$Answer a real JAMB 2003 question on Laboratory Preparation of Chlorine.$q$, $q$[{"conceptId": "w3jjz5", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "This reaction (conc. H2SO4 + NaCl) produces hydrogen chloride gas, not chlorine \u2014 a well-known but different laboratory gas-preparation reaction that's easy to confuse with chlorine preparation.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Potassium tetraoxomanganate(VII) (KMnO4) with concentrated HCl is a real alternative way to generate chlorine without heating, but it isn't the standard method emphasised as THE laboratory preparation in the syllabus \u2014 a plausible but secondary method mistaken for the primary one.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Potassium heptaoxodichromate(VI) (K2Cr2O7) can also oxidise concentrated HCl to some extent, but it isn't the standard, syllabus-taught method for preparing chlorine in the laboratory.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Chlorine gas is prepared in the laboratory by$q$, $q$[{"label": "A", "text": "adding concentrated hydrochloric acid to solid manganese(IV) oxide", "isCorrect": true}, {"label": "B", "text": "adding concentrated tetraoxosulphate(VI) acid to solid sodium chloride", "isCorrect": false}, {"label": "C", "text": "dropping concentrated hydrochloric acid onto potassium tetraoxomanganate(VII) crystals", "isCorrect": false}, {"label": "D", "text": "oxidizing concentrated hydrochloric acid using potassium heptaoxodichromate(VI) crystals", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$The standard laboratory preparation of chlorine, as emphasised in the syllabus, is MnO2(s) + 4HCl(conc) → MnCl2 + Cl2 + 2H2O (with gentle heating) — manganese(IV) oxide oxidising concentrated hydrochloric acid to release chlorine gas.$q$, $q$live$q$, $q$B: This reaction (conc. H2SO4 + NaCl) produces hydrogen chloride gas, not chlorine — a well-known but different laboratory gas-preparation reaction that's easy to confuse with chlorine preparation. C: Potassium tetraoxomanganate(VII) (KMnO4) with concentrated HCl is a real alternative way to generate chlorine without heating, but it isn't the standard method emphasised as THE laboratory preparation in the syllabus — a plausible but secondary method mistaken for the primary one. D: Potassium heptaoxodichromate(VI) (K2Cr2O7) can also oxidise concentrated HCl to some extent, but it isn't the standard, syllabus-taught method for preparing chlorine in the laboratory.$q$),
($q$chemistry_0405$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Transition Metals and d-Orbitals$q$, $q$Answer a real JAMB 2003 question on Transition Metals and d-Orbitals.$q$, $q$[{"conceptId": "aixz7h", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Group 1 metals themselves have filled s orbitals in their outer shells but aren't defined by partial filling of s orbitals \u2014 and this isn't the shell that distinguishes transition metals from other groups.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "p orbitals are relevant to main-group elements (like groups 13-18), not to the defining feature of transition metals.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "f orbitals are partially filled in the lanthanides and actinides (inner transition metals), a related but distinct category from the d-block transition metals this question describes.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Metals of the transition series have special properties which are different from those of groups 1 and 11 elements because they have partially filled$q$, $q$[{"label": "A", "text": "s orbitals", "isCorrect": false}, {"label": "B", "text": "p orbitals", "isCorrect": false}, {"label": "C", "text": "d orbitals", "isCorrect": true}, {"label": "D", "text": "f orbitals", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Transition metals are specifically defined by having partially filled d orbitals (or forming ions with partially filled d orbitals), which is the source of their characteristic properties: variable oxidation states, coloured compounds, and catalytic activity.$q$, $q$live$q$, $q$A: Group 1 metals themselves have filled s orbitals in their outer shells but aren't defined by partial filling of s orbitals — and this isn't the shell that distinguishes transition metals from other groups. B: p orbitals are relevant to main-group elements (like groups 13-18), not to the defining feature of transition metals. D: f orbitals are partially filled in the lanthanides and actinides (inner transition metals), a related but distinct category from the d-block transition metals this question describes.$q$),
($q$chemistry_0406$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Amphoteric Metals$q$, $q$Answer a real JAMB 2003 question on Amphoteric Metals.$q$, $q$[{"conceptId": "q8of3z", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Iron doesn't react with alkaline (hydroxide) solutions to release hydrogen \u2014 it isn't amphoteric in the way tin is.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Copper is a relatively unreactive metal that doesn't react with alkaline solutions to liberate hydrogen at all.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Calcium is reactive with water and dilute acids, but it isn't the classic example of a metal that reacts with hot alkaline solution specifically \u2014 that amphoteric behaviour belongs to metals like tin, zinc, and aluminium.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Hydrogen can be displaced from a hot alkaline solution by$q$, $q$[{"label": "A", "text": "Fe", "isCorrect": false}, {"label": "B", "text": "Cu", "isCorrect": false}, {"label": "C", "text": "Ca", "isCorrect": false}, {"label": "D", "text": "Sn", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Tin is amphoteric — it reacts with both acids and hot concentrated alkalis, releasing hydrogen gas as it forms a stannate ion in the alkaline solution. Iron and copper don't react with alkaline solutions this way, and calcium's reactivity is characteristically with water/acids rather than being noted for this specific amphoteric alkali reaction.$q$, $q$live$q$, $q$A: Iron doesn't react with alkaline (hydroxide) solutions to release hydrogen — it isn't amphoteric in the way tin is. B: Copper is a relatively unreactive metal that doesn't react with alkaline solutions to liberate hydrogen at all. C: Calcium is reactive with water and dilute acids, but it isn't the classic example of a metal that reacts with hot alkaline solution specifically — that amphoteric behaviour belongs to metals like tin, zinc, and aluminium.$q$),
($q$chemistry_0407$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Sulphur Compounds$q$, $q$Answer a real JAMB 2003 question on Sulphur Compounds.$q$, $q$[{"conceptId": "2eamtt", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "SO2 dissolving in water forms sulphurous acid (H2SO3, sulphate(IV) acid) \u2014 not tetraoxosulphate(VI) acid (H2SO4), which is a different, more oxidised acid entirely.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "SO2 has a very distinctive sharp, choking, pungent smell \u2014 it is definitely not an odourless gas, making this factually the opposite of true.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "The white BaSO4 precipitate test with acidified barium chloride is characteristic of sulphate (SO4\u00b2\u207b, the fully oxidised S(VI) form) \u2014 SO2/sulphite doesn't give this precipitate under acidified conditions since BaSO3 is soluble in dilute acid.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Which of the following statements is true of sulphur(IV) oxide?$q$, $q$[{"label": "A", "text": "It forms tetraoxosulphate(VI) acid with water", "isCorrect": false}, {"label": "B", "text": "It is an odourless gas", "isCorrect": false}, {"label": "C", "text": "It is an acid anhydride", "isCorrect": true}, {"label": "D", "text": "It forms a white precipitate with acidified barium chloride", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Sulphur(IV) oxide (SO2) is the acid anhydride of sulphurous acid (tetraoxosulphate(IV) acid, H2SO3) — it forms H2SO3, not H2SO4, when dissolved in water. It has a sharp, pungent (not odourless) smell, and being an unoxidised sulphite in solution, it does not give the white BaSO4 precipitate with acidified barium chloride the way a true sulphate does.$q$, $q$live$q$, $q$A: SO2 dissolving in water forms sulphurous acid (H2SO3, sulphate(IV) acid) — not tetraoxosulphate(VI) acid (H2SO4), which is a different, more oxidised acid entirely. B: SO2 has a very distinctive sharp, choking, pungent smell — it is definitely not an odourless gas, making this factually the opposite of true. D: The white BaSO4 precipitate test with acidified barium chloride is characteristic of sulphate (SO4²⁻, the fully oxidised S(VI) form) — SO2/sulphite doesn't give this precipitate under acidified conditions since BaSO3 is soluble in dilute acid.$q$),
($q$chemistry_0408$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$Qualitative Analysis of Ions$q$, $q$Answer a real JAMB 2003 question on Qualitative Analysis of Ions.$q$, $q$[{"conceptId": "kv2dlm", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Calcium hydroxide is only sparingly soluble and doesn't reliably form a clear precipitate with ammonia in the way transition metal hydroxides do \u2014 it doesn't fit this specific 'precipitate that dissolves in excess ammonia' behaviour.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Mg(OH)2 does precipitate with ammonia, but unlike copper's hydroxide, it stays insoluble even when excess ammonia is added \u2014 magnesium doesn't form the soluble ammine complex that copper does.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "Al(OH)3 precipitates with ammonia but also remains insoluble in excess \u2014 aluminium, unlike copper, does not form a soluble complex with excess ammonia.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$The salt that will form a precipitate soluble in excess ammonia solution is$q$, $q$[{"label": "A", "text": "Ca(NO3)2", "isCorrect": false}, {"label": "B", "text": "Cu(NO3)2", "isCorrect": true}, {"label": "C", "text": "Mg(NO3)2", "isCorrect": false}, {"label": "D", "text": "Al(NO3)3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Cu(NO3)2 forms a pale blue Cu(OH)2 precipitate with ammonia, which then DISSOLVES in excess ammonia to form the deep blue tetraamminecopper(II) complex, [Cu(NH3)4]2+ — a classic distinguishing test. Ca(NO3)2 doesn't reliably form a precipitate with ammonia; Mg(OH)2 and Al(OH)3 precipitates both form but stay insoluble even in excess ammonia.$q$, $q$live$q$, $q$A: Calcium hydroxide is only sparingly soluble and doesn't reliably form a clear precipitate with ammonia in the way transition metal hydroxides do — it doesn't fit this specific 'precipitate that dissolves in excess ammonia' behaviour. C: Mg(OH)2 does precipitate with ammonia, but unlike copper's hydroxide, it stays insoluble even when excess ammonia is added — magnesium doesn't form the soluble ammine complex that copper does. D: Al(OH)3 precipitates with ammonia but also remains insoluble in excess — aluminium, unlike copper, does not form a soluble complex with excess ammonia.$q$),
($q$chemistry_0409$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$General Reactivity Facts$q$, $q$Answer a real JAMB 2003 question on General Reactivity Facts.$q$, $q$[{"conceptId": "vfmsto", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Sodium reacts with cold water violently \u2014 often skating across the surface and sometimes catching fire \u2014 far more dramatic than a simple, steady stream of bubbles.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Potassium reacts even more violently than sodium with cold water, typically igniting the released hydrogen \u2014 nothing like a controlled 'bubbles only' reaction.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Aluminium does not react with cold water at all under ordinary conditions \u2014 its protective oxide layer prevents any reaction, so it releases no hydrogen this way whatsoever.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$The metal that liberates hydrogen from cold water in bubbles only is$q$, $q$[{"label": "A", "text": "Na", "isCorrect": false}, {"label": "B", "text": "K", "isCorrect": false}, {"label": "C", "text": "Ca", "isCorrect": true}, {"label": "D", "text": "Al", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Calcium reacts with cold water at a controlled, steady rate, producing a visible stream of hydrogen bubbles without the violent, often flame-producing reaction seen with sodium and potassium. Aluminium, by contrast, does not react with cold water at all under normal conditions, protected by its tough oxide layer.$q$, $q$live$q$, $q$A: Sodium reacts with cold water violently — often skating across the surface and sometimes catching fire — far more dramatic than a simple, steady stream of bubbles. B: Potassium reacts even more violently than sodium with cold water, typically igniting the released hydrogen — nothing like a controlled 'bubbles only' reaction. D: Aluminium does not react with cold water at all under ordinary conditions — its protective oxide layer prevents any reaction, so it releases no hydrogen this way whatsoever.$q$),
($q$chemistry_0410$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Halogens — Starch-Iodide Test$q$, $q$Answer a real JAMB 2003 question on Halogens — Starch-Iodide Test.$q$, $q$[{"conceptId": "izl9kl", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Pink isn't the colour produced by this classic test \u2014 the starch-iodine complex is specifically a deep blue/blue-black colour, not pink.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "The paper doesn't turn colourless \u2014 chlorine actively generates a coloured product (iodine trapped by starch), the opposite of a colourless result.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Red isn't the characteristic colour of the starch-iodine complex \u2014 this test is specifically known for its dark blue/blue-black colour change, a distinctive and often-tested fact.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Chlorine gas turns a damp starch-iodide paper$q$, $q$[{"label": "A", "text": "pink", "isCorrect": false}, {"label": "B", "text": "colourless", "isCorrect": false}, {"label": "C", "text": "red", "isCorrect": false}, {"label": "D", "text": "dark blue", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Chlorine is a strong enough oxidising agent to displace iodine from iodide ions on the paper (Cl2 + 2I- → 2Cl- + I2). The liberated iodine then forms its characteristic deep blue-black complex with the starch present on the paper.$q$, $q$live$q$, $q$A: Pink isn't the colour produced by this classic test — the starch-iodine complex is specifically a deep blue/blue-black colour, not pink. B: The paper doesn't turn colourless — chlorine actively generates a coloured product (iodine trapped by starch), the opposite of a colourless result. C: Red isn't the characteristic colour of the starch-iodine complex — this test is specifically known for its dark blue/blue-black colour change, a distinctive and often-tested fact.$q$),
($q$chemistry_0411$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Steel Manufacture$q$, $q$Answer a real JAMB 2003 question on Steel Manufacture.$q$, $q$[{"conceptId": "v5b5h3", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Steelmaking doesn't involve treating iron with acids \u2014 the impurity-removal step is achieved through oxidation (blowing oxygen through the melt), not acid treatment.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "'Blast reduction' describes how iron ORE is reduced to iron in the blast furnace (an earlier, separate stage) \u2014 converting that iron into steel is a different, subsequent process based on oxidation, not further reduction.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Steelmaking doesn't use alkali treatment \u2014 the key chemistry is oxidising away excess carbon and impurities from the molten iron using oxygen gas.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$The modern process of manufacturing steel from iron is by$q$, $q$[{"label": "A", "text": "treatment with acids", "isCorrect": false}, {"label": "B", "text": "oxidation", "isCorrect": true}, {"label": "C", "text": "blast reduction", "isCorrect": false}, {"label": "D", "text": "treatment with alkalis", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Converting iron (pig iron, containing excess carbon and other impurities from the blast furnace) into steel involves blowing oxygen through the molten iron to oxidise and remove the excess carbon and impurities — this is fundamentally an oxidation process (e.g. the Basic Oxygen Process).$q$, $q$live$q$, $q$A: Steelmaking doesn't involve treating iron with acids — the impurity-removal step is achieved through oxidation (blowing oxygen through the melt), not acid treatment. C: 'Blast reduction' describes how iron ORE is reduced to iron in the blast furnace (an earlier, separate stage) — converting that iron into steel is a different, subsequent process based on oxidation, not further reduction. D: Steelmaking doesn't use alkali treatment — the key chemistry is oxidising away excess carbon and impurities from the molten iron using oxygen gas.$q$),
($q$chemistry_0412$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Alkenes — Addition Reactions$q$, $q$Answer a real JAMB 2003 question on Alkenes — Addition Reactions.$q$, $q$[{"conceptId": "ace3du", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "CH2Br2 (dibromomethane) has the wrong carbon skeleton entirely (only 1 carbon's worth of substitution pattern) and doesn't match the 2-carbon product expected from ethene addition.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "C2H2Br2 assumes two bromine atoms add to ethene, but only one HBr molecule reacts in a simple addition \u2014 this double-counts the bromine incorporated into the product.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "CHBr3 (bromoform) has three bromine atoms and the wrong overall structure \u2014 nowhere close to the simple one-to-one HBr addition product expected here.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Ethene reacts with hydrogen bromide to give$q$, $q$[{"label": "A", "text": "CH2Br2", "isCorrect": false}, {"label": "B", "text": "CH3CH2Br", "isCorrect": true}, {"label": "C", "text": "C2H2Br2", "isCorrect": false}, {"label": "D", "text": "CHBr3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$HBr adds across ethene's C=C double bond in a simple addition reaction: CH2=CH2 + HBr → CH3CH2Br (bromoethane). Only one H and one Br are added, one to each carbon, with no other change to the molecule.$q$, $q$live$q$, $q$A: CH2Br2 (dibromomethane) has the wrong carbon skeleton entirely (only 1 carbon's worth of substitution pattern) and doesn't match the 2-carbon product expected from ethene addition. C: C2H2Br2 assumes two bromine atoms add to ethene, but only one HBr molecule reacts in a simple addition — this double-counts the bromine incorporated into the product. D: CHBr3 (bromoform) has three bromine atoms and the wrong overall structure — nowhere close to the simple one-to-one HBr addition product expected here.$q$),
($q$chemistry_0413$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Carbohydrates — Identification and Formula$q$, $q$Answer a real JAMB 2003 question on Carbohydrates — Identification and Formula.$q$, $q$[{"conceptId": "d1sp6r", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "3:1:1 doesn't match the defining 'hydrate of carbon' pattern (Cx(H2O)y) that gives carbohydrates their name and general formula.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "2:1:1 inverts the actual carbon-to-hydrogen relationship \u2014 carbohydrates have MORE hydrogen than carbon (2 H per C), not the other way around.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "1:1:1 doesn't reflect the actual water-like H:O ratio (2:1) that defines carbohydrates as 'hydrates' of carbon.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Carbohydrates are compounds containing carbon, hydrogen and oxygen in the ratio$q$, $q$[{"label": "A", "text": "3:1:1", "isCorrect": false}, {"label": "B", "text": "2:1:1", "isCorrect": false}, {"label": "C", "text": "1:2:1", "isCorrect": true}, {"label": "D", "text": "1:1:1", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Carbohydrates have the general formula Cx(H2O)y, meaning for every carbon atom there are 2 hydrogen atoms and 1 oxygen atom — a C:H:O ratio of 1:2:1, reflecting that they're literally 'hydrates of carbon'.$q$, $q$live$q$, $q$A: 3:1:1 doesn't match the defining 'hydrate of carbon' pattern (Cx(H2O)y) that gives carbohydrates their name and general formula. B: 2:1:1 inverts the actual carbon-to-hydrogen relationship — carbohydrates have MORE hydrogen than carbon (2 H per C), not the other way around. D: 1:1:1 doesn't reflect the actual water-like H:O ratio (2:1) that defines carbohydrates as 'hydrates' of carbon.$q$),
($q$chemistry_0414$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Isomerism$q$, $q$Answer a real JAMB 2003 question on Isomerism.$q$, $q$[{"conceptId": "j32bof", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "6 overcounts \u2014 there are only three genuinely distinct structural arrangements possible for a 5-carbon alkane, not six.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "5 overcounts pentane's isomers \u2014 this number is closer to hexane's isomer count (5), which may be where the confusion arises from mixing up different alkanes.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "4 overcounts by one \u2014 a common near-miss when trying to enumerate branching patterns without systematically checking for duplicate/equivalent structures.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$How many isomers does pentane have?$q$, $q$[{"label": "A", "text": "6", "isCorrect": false}, {"label": "B", "text": "5", "isCorrect": false}, {"label": "C", "text": "4", "isCorrect": false}, {"label": "D", "text": "3", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$C5H12 (pentane) has exactly three structural isomers: n-pentane (straight chain), 2-methylbutane (isopentane), and 2,2-dimethylpropane (neopentane).$q$, $q$live$q$, $q$A: 6 overcounts — there are only three genuinely distinct structural arrangements possible for a 5-carbon alkane, not six. B: 5 overcounts pentane's isomers — this number is closer to hexane's isomer count (5), which may be where the confusion arises from mixing up different alkanes. C: 4 overcounts by one — a common near-miss when trying to enumerate branching patterns without systematically checking for duplicate/equivalent structures.$q$),
($q$chemistry_0415$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Functional Group Identification — Esters$q$, $q$Answer a real JAMB 2003 question on Functional Group Identification — Esters.$q$, $q$[{"conceptId": "kmmznm", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "This swaps which part is the acid and which is the alcohol \u2014 C2H5COO- would be from propanoic acid (propanoate), and C3H7- would be the alcohol's alkyl part (propyl), the reverse of 'ethyl butanoate'.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "C4H9- as the acid portion would come from pentanoic acid (pentanoate), not butanoic acid \u2014 this has one carbon too many in the acid-derived part.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This combines butanoic acid's acyl part correctly-ish reversed with a butyl (C4H9) alcohol group instead of ethyl \u2014 mismatching which alkyl group belongs to 'ethyl' butanoate.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$The formula for ethyl butanoate is$q$, $q$[{"label": "A", "text": "C3H7COOC2H5", "isCorrect": true}, {"label": "B", "text": "C2H5COOC3H7", "isCorrect": false}, {"label": "C", "text": "C4H9COOC2H5", "isCorrect": false}, {"label": "D", "text": "C2H5COOC4H9", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Ester naming follows 'alkyl alkanoate': the alkyl part (ethyl, C2H5) comes from the alcohol, and the alkanoate part (butanoate, from butanoic acid, C3H7COOH) comes from the acid. So ethyl butanoate = C3H7COO-C2H5, with the acid's carbon chain (C3H7-COO-) written first and the alcohol's alkyl group (ethyl) second.$q$, $q$live$q$, $q$B: This swaps which part is the acid and which is the alcohol — C2H5COO- would be from propanoic acid (propanoate), and C3H7- would be the alcohol's alkyl part (propyl), the reverse of 'ethyl butanoate'. C: C4H9- as the acid portion would come from pentanoic acid (pentanoate), not butanoic acid — this has one carbon too many in the acid-derived part. D: This combines butanoic acid's acyl part correctly-ish reversed with a butyl (C4H9) alcohol group instead of ethyl — mismatching which alkyl group belongs to 'ethyl' butanoate.$q$),
($q$chemistry_0416$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Benzene and Aromatic Substitution$q$, $q$Answer a real JAMB 2003 question on Benzene and Aromatic Substitution.$q$, $q$[{"conceptId": "uej13e", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Addition reactions are typical of simple alkenes with isolated C=C double bonds \u2014 benzene's special aromatic stability actually makes it resist addition, favouring substitution instead.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Hydrolysis isn't a characteristic reaction type of benzene's aromatic ring at all \u2014 it's more relevant to esters, amides, and similar functional groups.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Polymerization isn't the defining or 'peculiar' reaction associated with benzene \u2014 that distinction belongs to compounds with reactive double/triple bonds meant for chain-building, not benzene's stable ring system.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$The type of reaction that is peculiar to benzene is$q$, $q$[{"label": "A", "text": "addition", "isCorrect": false}, {"label": "B", "text": "hydrolysis", "isCorrect": false}, {"label": "C", "text": "polymerization", "isCorrect": false}, {"label": "D", "text": "substitution", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Despite benzene's ring containing what looks like alternating double bonds, its special aromatic stability (delocalised pi electron system) makes it resistant to the addition reactions typical of alkenes — instead, benzene characteristically undergoes electrophilic substitution, preserving its stable ring while swapping out a hydrogen for another group.$q$, $q$live$q$, $q$A: Addition reactions are typical of simple alkenes with isolated C=C double bonds — benzene's special aromatic stability actually makes it resist addition, favouring substitution instead. B: Hydrolysis isn't a characteristic reaction type of benzene's aromatic ring at all — it's more relevant to esters, amides, and similar functional groups. C: Polymerization isn't the defining or 'peculiar' reaction associated with benzene — that distinction belongs to compounds with reactive double/triple bonds meant for chain-building, not benzene's stable ring system.$q$),
($q$chemistry_0417$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Oxidation of Alcohols$q$, $q$Answer a real JAMB 2003 question on Oxidation of Alcohols.$q$, $q$[{"conceptId": "4f68ue", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Ethanedioic acid (oxalic acid, HOOC-COOH) has two carboxylic acid groups and two carbons in a different arrangement \u2014 full oxidation of ethanol's single -CH2OH group doesn't produce this diacid.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "Ethanol is the starting material, not the product \u2014 this option describes no reaction happening at all, when in fact excess oxidant clearly transforms it.", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "Ethyl ethanoate is an ester, formed by combining an alcohol and an acid (esterification) \u2014 not the direct oxidation product of ethanol reacting with an oxidising agent like dichromate.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Ethanol reacts with excess acidified K2Cr2O7 to give$q$, $q$[{"label": "A", "text": "ethanedioic acid", "isCorrect": false}, {"label": "B", "text": "ethanol", "isCorrect": false}, {"label": "C", "text": "ethyl ethanoate", "isCorrect": false}, {"label": "D", "text": "ethanoic acid", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$With EXCESS acidified dichromate (a strong, plentiful oxidising agent), ethanol is fully oxidised all the way through the aldehyde intermediate (ethanal) to the carboxylic acid — ethanoic acid — the final oxidation product for a primary alcohol under these conditions.$q$, $q$live$q$, $q$A: Ethanedioic acid (oxalic acid, HOOC-COOH) has two carboxylic acid groups and two carbons in a different arrangement — full oxidation of ethanol's single -CH2OH group doesn't produce this diacid. B: Ethanol is the starting material, not the product — this option describes no reaction happening at all, when in fact excess oxidant clearly transforms it. C: Ethyl ethanoate is an ester, formed by combining an alcohol and an acid (esterification) — not the direct oxidation product of ethanol reacting with an oxidising agent like dichromate.$q$),
($q$chemistry_0418$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Empirical and Molecular Formula$q$, $q$Answer a real JAMB 2003 question on Empirical and Molecular Formula.$q$, $q$[{"conceptId": "mu9d5t", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 84, $q$medium$q$, $q$heavy$q$, $q$[{"option": "A", "explanation": "CH2O is the empirical formula, not the molecular formula \u2014 the question specifically asks for the molecular formula, which must account for the full given molar mass of 180, six times larger than CH2O's mass of 30.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "C3H6O3 is only 3 times the empirical unit (mass 90), not 6 times \u2014 this doesn't match the given molar mass of 180.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "C6H6O3 has the correct multiplier applied to carbon and oxygen but not to hydrogen \u2014 the empirical ratio's hydrogen count (2 per C) wasn't scaled consistently with the rest.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$A compound contains 40.0% carbon, 6.7% hydrogen and 53.3% oxygen. If the molar mass of the compound is 180, find the molecular formula. [H = 1, C = 12, O = 16]$q$, $q$[{"label": "A", "text": "CH2O", "isCorrect": false}, {"label": "B", "text": "C3H6O3", "isCorrect": false}, {"label": "C", "text": "C6H12O6", "isCorrect": true}, {"label": "D", "text": "C6H6O3", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Empirical formula: C = 40/12 = 3.33; H = 6.7/1 = 6.7; O = 53.3/16 = 3.33. Dividing by the smallest (3.33) gives a ratio of 1 : 2.01 : 1, i.e. CH2O (empirical formula mass = 30). Since molar mass = 180, the multiplier n = 180/30 = 6, giving molecular formula C6H12O6 (glucose).$q$, $q$live$q$, $q$A: CH2O is the empirical formula, not the molecular formula — the question specifically asks for the molecular formula, which must account for the full given molar mass of 180, six times larger than CH2O's mass of 30. B: C3H6O3 is only 3 times the empirical unit (mass 90), not 6 times — this doesn't match the given molar mass of 180. D: C6H6O3 has the correct multiplier applied to carbon and oxygen but not to hydrogen — the empirical ratio's hydrogen count (2 per C) wasn't scaled consistently with the rest.$q$),
($q$chemistry_0419$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Petroleum Refining$q$, $q$Answer a real JAMB 2003 question on Petroleum Refining.$q$, $q$[{"conceptId": "yxuq7s", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$medium$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Catalytic cracking breaks larger hydrocarbon molecules into smaller ones \u2014 it changes molecular SIZE, not just rearranges structure while keeping size the same.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Hydrocracking, like catalytic cracking, breaks molecules apart (using hydrogen) into smaller fragments \u2014 again a size-changing process, not the structure-rearranging process being described.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Polymerization combines smaller molecules into larger ones \u2014 the opposite direction of change from what's being asked (rearranging structure, not changing overall molecular size).", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$The process by which atoms are rearranged into different molecular structures in the petroleum refining process is referred to as$q$, $q$[{"label": "A", "text": "catalytic cracking", "isCorrect": false}, {"label": "B", "text": "hydrocracking", "isCorrect": false}, {"label": "C", "text": "polymerization", "isCorrect": false}, {"label": "D", "text": "reforming", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Reforming rearranges the structure of hydrocarbon molecules (e.g. converting straight-chain alkanes into branched or aromatic ones) without necessarily changing their size — improving fuel quality (like octane rating) through structural rearrangement, distinct from cracking (which breaks molecules into smaller ones) or polymerization (which joins molecules into larger ones).$q$, $q$live$q$, $q$A: Catalytic cracking breaks larger hydrocarbon molecules into smaller ones — it changes molecular SIZE, not just rearranges structure while keeping size the same. B: Hydrocracking, like catalytic cracking, breaks molecules apart (using hydrogen) into smaller fragments — again a size-changing process, not the structure-rearranging process being described. C: Polymerization combines smaller molecules into larger ones — the opposite direction of change from what's being asked (rearranging structure, not changing overall molecular size).$q$),
($q$chemistry_0420$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Natural Macromolecules — Cellulose$q$, $q$Answer a real JAMB 2003 question on Natural Macromolecules — Cellulose.$q$, $q$[{"conceptId": "wk11wx", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Starch is a storage polysaccharide found in plant seeds/tubers (like potatoes, rice) \u2014 cotton's fibrous structural component is cellulose, a chemically related but functionally different polysaccharide.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Fat is a lipid, structurally and functionally unrelated to the polysaccharide fibres that make up cotton.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Oil, like fat, is a lipid \u2014 cotton fibre's composition is carbohydrate-based (cellulose), not lipid-based.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$Which of the following is found in cotton?$q$, $q$[{"label": "A", "text": "Starch", "isCorrect": false}, {"label": "B", "text": "Cellulose", "isCorrect": true}, {"label": "C", "text": "Fat", "isCorrect": false}, {"label": "D", "text": "Oil", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Cotton fibres are composed almost entirely of cellulose, a structural polysaccharide that gives plant cell walls (and cotton fibres specifically) their strength and fibrous character.$q$, $q$live$q$, $q$A: Starch is a storage polysaccharide found in plant seeds/tubers (like potatoes, rice) — cotton's fibrous structural component is cellulose, a chemically related but functionally different polysaccharide. C: Fat is a lipid, structurally and functionally unrelated to the polysaccharide fibres that make up cotton. D: Oil, like fat, is a lipid — cotton fibre's composition is carbohydrate-based (cellulose), not lipid-based.$q$),
($q$chemistry_0421$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Natural Gas Composition$q$, $q$Answer a real JAMB 2003 question on Natural Gas Composition.$q$, $q$[{"conceptId": "xlxlql", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Ethane is present in natural gas only as a minor component, far behind methane's dominant share.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Propane is a minor component of natural gas (often separated out as LPG) \u2014 not the principal constituent.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Butane, like propane, is only a minor component of natural gas, typically separated out for other uses (e.g. LPG) rather than being the main constituent.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2003, $q$JAMB$q$, $q$The principal constituent of natural gas is$q$, $q$[{"label": "A", "text": "methane", "isCorrect": true}, {"label": "B", "text": "ethane", "isCorrect": false}, {"label": "C", "text": "propane", "isCorrect": false}, {"label": "D", "text": "butane", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Natural gas is overwhelmingly composed of methane (typically 70-90%), with much smaller amounts of ethane, propane, and butane present as minor components.$q$, $q$live$q$, $q$B: Ethane is present in natural gas only as a minor component, far behind methane's dominant share. C: Propane is a minor component of natural gas (often separated out as LPG) — not the principal constituent. D: Butane, like propane, is only a minor component of natural gas, typically separated out for other uses (e.g. LPG) rather than being the main constituent.$q$);;
